/* Built-in artwork (generated by tools/make_brand.py into brand_data.c): the
 * logo, button prompts and region flags. UI text is drawn in Jost (ui.h). */
#ifndef GBADS_BRAND_H
#define GBADS_BRAND_H

#include <stddef.h>

enum { BRAND_LOGO, BRAND_BTN_A, BRAND_BTN_B, BRAND_BTN_L1, BRAND_BTN_R1,
       BRAND_FLAG_US, BRAND_FLAG_EU, BRAND_FLAG_JP, BRAND_FLAG_FR, BRAND_FLAG_DE,
       BRAND_BTN_L, BRAND_BTN_R, BRAND_PILL_L, BRAND_PILL_R, BRAND_COUNT };

typedef struct {
	const unsigned char* png;
	size_t size;
} BrandImage;

extern const BrandImage brandImages[BRAND_COUNT];

#endif
